package com.enterpriseflow.repository; import com.enterpriseflow.entity.Document; import org.springframework.data.jpa.repository.*; import org.springframework.data.repository.query.Param; import java.util.*; public interface DocumentRepository extends JpaRepository<Document,UUID>{@EntityGraph(attributePaths="owner") List<Document> findByProjectIdAndArchivedFalse(UUID projectId); @Query("select d from Document d where lower(d.title) like lower(concat('%',:q,'%')) or lower(coalesce(d.extractedText,'')) like lower(concat('%',:q,'%'))") List<Document> search(@Param("q") String q);}
